import React, { useEffect, useState } from "react";
import Layout from "../components/Layout";
import api from "../api/axios";
import "./IDCardPage.css";

function IDCardPage() {
  const [cards, setCards] = useState([]);
  const [apps, setApps] = useState([]);

  const load = async () => {
    const cardsRes = await api.get("/api/id-cards/");
    const appsRes = await api.get("/api/applications/");
    setCards(cardsRes.data);
    setApps(appsRes.data.filter((x) => x.status === "Committee Approved"));
  };

  useEffect(() => { load(); }, []);

  const generate = async (id) => {
    await api.post(`/api/id-cards/generate/${id}`);
    load();
  };

  return (
    <Layout>
      <div className="cards-grid">
        <div className="page-card">
          <h2>Generate ID Card</h2>
          <table className="data-table">
            <thead><tr><th>App No</th><th>Name</th><th>Category</th><th>Generate</th></tr></thead>
            <tbody>
              {apps.map((item) => (
                <tr key={item.id}>
                  <td>{item.application_no}</td>
                  <td>{item.full_name}</td>
                  <td>{item.disability_severity}</td>
                  <td><button className="primary-btn" onClick={() => generate(item.id)}>Generate</button></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div className="page-card">
          <h2>Generated Cards</h2>
          <table className="data-table">
            <thead><tr><th>Card No</th><th>Name</th><th>Type</th><th>Status</th></tr></thead>
            <tbody>
              {cards.map((card) => (
                <tr key={card.id}>
                  <td>{card.card_number}</td>
                  <td>{card.application?.full_name || ""}</td>
                  <td>{card.card_type}</td>
                  <td>{card.card_status}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </Layout>
  );
}

export default IDCardPage;
